/**
 * DEMO DATASET -- synthetic records for interface development only.
 *
 * Section 44 of the build spec allows mock data during development provided it
 * is visibly labelled. Every record below carries `isDemo: true`, which drives
 * the DEMO DATA banner in the header and a badge on every card and figure.
 *
 * These numbers are generated by the helper at the bottom of this file. They
 * are NOT measurements of the named platforms, and no real Dune query, dataset
 * or research paper is cited for them -- attaching a real-looking source to a
 * synthetic number is precisely the failure mode this site exists to prevent.
 * Every demo source is marked provider "DEMO", status UNVERIFIED, url null.
 *
 * In production mode (DATA_MODE=production) this file is not loaded at all.
 */

const DEMO_METHODOLOGY = (version: string): Methodology => ({
  pnlDefinition:
    "Realised PnL per wallet: proceeds from closes and sells minus cost basis of opens and buys, in USD at transaction time.",
  feesIncluded: true,
  unrealizedIncluded: false,
  walletClustering: false,
  exclusions: [
    "Wallets with fewer than 2 transactions in the window",
    "Known platform, router and market-maker addresses",
    "Transactions that failed or reverted",
  ],
  filters: ["Window bounded by dataset dates", "USD conversion at block timestamp"],
  dateRangeStart: "2025-01-01",
  dateRangeEnd: "2025-08-15",
  calculationVersion: version,
  notes:
    "Synthetic demonstration record. Not a measurement of the named platform. Present only to exercise the interface.",
});

function demoSources(slug: string): EvidenceSource[] {
  return [
    {
      id: `${slug}-demo-primary`,
      role: "primary",
      provider: "DEMO",
      // Not "onchain-raw": a placeholder must not claim a data class it does
      // not have, or the evidence score credits it +30 for chain data that
      // does not exist.
      type: "aggregator",
      url: null,
      query: `-- DEMO RECORD. This is not a real query and returns no real result.\n-- Replace with a published, re-runnable query before this platform\n-- can leave the review queue.\nSELECT 'insufficient verifiable data' AS status;`,
      datasetDate: "2025-08-15",
      lastVerified: "2025-08-15",
      sampleSize: null,
      reproducible: false,
      status: "UNVERIFIED",
      notes: "Synthetic placeholder. No real dataset is attached to this record.",
    },
  ];
}

interface DemoSpec {
  slug: string;
  name: string;
  category: Category;
  description: string;
  chains: string[];
  website: string | null;
  analyzed: number;
  profitableShare: number;
  breakEvenShare: number;
  unknownShare: number;
  medianPnlUsd: number;
  meanPnlUsd: number;
  topOnePctProfitShare: number;
  /** Profitable share at each activity band, as a multiplier on the baseline. */
  activityDecay: number;
}

/** Deterministic pseudo-random so the demo build is byte-stable. */
function seeded(seed: string): () => number {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i += 1) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return () => {
    h += 0x6d2b79f5;
    let t = h;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const BUCKET_EDGES: Array<{ min: number | null; max: number | null; label: string }> = [
  { min: null, max: -10_000, label: "< -$10k" },
  { min: -10_000, max: -1_000, label: "-$10k to -$1k" },
  { min: -1_000, max: -100, label: "-$1k to -$100" },
  { min: -100, max: 0, label: "-$100 to $0" },
  { min: 0, max: 100, label: "$0 to $100" },
  { min: 100, max: 1_000, label: "$100 to $1k" },
  { min: 1_000, max: 10_000, label: "$1k to $10k" },
  { min: 10_000, max: null, label: "> $10k" },
];

function buildBuckets(spec: DemoSpec, counts: WalletCounts): PnlBucket[] {
  const rand = seeded(`${spec.slug}-buckets`);
  const losing = counts.unprofitable;
  const winning = counts.profitable;
  // Losses concentrate in the small-loss buckets; wins have a long thin tail.
  const lossWeights = [0.03, 0.14, 0.38, 0.45];
  const winWeights = [0.52, 0.32, 0.13, 0.03];

  const lossCounts = distribute(losing, lossWeights, rand);
  const winCounts = distribute(winning, winWeights, rand);
  const all = [...lossCounts, ...winCounts];

  return BUCKET_EDGES.map((edge, i) => ({ ...edge, wallets: all[i] ?? 0 }));
}

/** Split a total across weights, with the remainder landing on the largest. */
function distribute(total: number, weights: number[], rand: () => number): number[] {
  const jittered = weights.map((w) => w * (0.92 + rand() * 0.16));
  const sum = jittered.reduce((a, b) => a + b, 0);
  const raw = jittered.map((w) => Math.floor((w / sum) * total));
  const remainder = total - raw.reduce((a, b) => a + b, 0);
  const largest = raw.indexOf(Math.max(...raw));
  raw[largest] += remainder;
  return raw;
}

const ACTIVITY_BANDS: Array<{ label: string; minTrades: number; share: number }> = [
  { label: "All wallets", minTrades: 0, share: 1 },
  { label: "10+ trades", minTrades: 10, share: 0.38 },
  { label: "50+ trades", minTrades: 50, share: 0.12 },
  { label: "100+ trades", minTrades: 100, share: 0.055 },
  { label: "500+ trades", minTrades: 500, share: 0.011 },
];

function buildActivityBands(spec: DemoSpec, counts: WalletCounts): ActivityBand[] {
  const baseline = counts.profitable / counts.analyzed;
  return ACTIVITY_BANDS.map((band, i) => {
    const wallets = Math.round(counts.analyzed * band.share);
    const rate = baseline * Math.pow(spec.activityDecay, i);
    return { label: band.label, minTrades: band.minTrades, wallets, profitable: Math.round(wallets * rate) };
  });
}

const SURVIVOR_THRESHOLDS = [1, 100, 1_000, 10_000, 100_000];

function buildSurvivorBands(spec: DemoSpec, counts: WalletCounts, buckets: PnlBucket[]): SurvivorBand[] {
  const above = (threshold: number) =>
    buckets.filter((b) => (b.min ?? -Infinity) >= threshold).reduce((s, b) => s + b.wallets, 0);
  const rand = seeded(`${spec.slug}-survivors`);
  return SURVIVOR_THRESHOLDS.map((threshold) => {
    // Interpolate inside buckets for thresholds that do not land on an edge.
    const exact = above(threshold);
    const scaled = threshold === 1 ? counts.profitable : Math.round(exact * (0.7 + rand() * 0.3));
    return {
      threshold,
      label: threshold === 1 ? "$1+" : `$${threshold.toLocaleString()}+`,
      wallets: Math.min(counts.profitable, scaled),
    };
  });
}

const TIMEFRAME_POINTS: Record<Timeframe, number> = { "7D": 7, "30D": 30, "90D": 12, "1Y": 12, ALL: 18 };

function buildSeries(spec: DemoSpec, counts: WalletCounts): Partial<Record<Timeframe, TimeSeriesPoint[]>> {
  const baseline = (counts.profitable / counts.analyzed) * 100;
  const out: Partial<Record<Timeframe, TimeSeriesPoint[]>> = {};
  (Object.keys(TIMEFRAME_POINTS) as Timeframe[]).forEach((tf) => {
    const rand = seeded(`${spec.slug}-${tf}`);
    const n = TIMEFRAME_POINTS[tf];
    const stepDays = tf === "7D" ? 1 : tf === "30D" ? 1 : tf === "90D" ? 7 : tf === "1Y" ? 30 : 30;
    out[tf] = Array.from({ length: n }, (_, i) => {
      const date = new Date(Date.UTC(2025, 7, 15));
      date.setUTCDate(date.getUTCDate() - (n - 1 - i) * stepDays);
      const drift = (rand() - 0.5) * 3.2;
      return {
        date: date.toISOString().slice(0, 10),
        profitablePct: Number(Math.max(0, baseline + drift).toFixed(2)),
        analyzed: Math.round((counts.analyzed / n) * (0.8 + rand() * 0.4)),
      };
    });
  });
  return out;
}

function buildStat(spec: DemoSpec): ProfitabilityStat {
  const profitable = Math.round(spec.analyzed * spec.profitableShare);
  const breakEven = Math.round(spec.analyzed * spec.breakEvenShare);
  const unknown = Math.round(spec.analyzed * spec.unknownShare);
  const counts: WalletCounts = {
    analyzed: spec.analyzed,
    profitable,
    breakEven,
    unknown,
    unprofitable: spec.analyzed - profitable - breakEven - unknown,
  };
  const buckets = buildBuckets(spec, counts);
  return {
    counts,
    medianPnlUsd: spec.medianPnlUsd,
    meanPnlUsd: spec.meanPnlUsd,
    topOnePctProfitShare: spec.topOnePctProfitShare,
    buckets,
    activityBands: buildActivityBands(spec, counts),
    survivorBands: buildSurvivorBands(spec, counts, buckets),
    series: buildSeries(spec, counts),
    methodology: DEMO_METHODOLOGY("demo-v1"),
    sources: demoSources(spec.slug),
    // Demo records never claim strong evidence. The score computes low, which
    // is the honest result for a record with no reproducible source.
    evidenceFactors: {
      officialOrRawChainData: false,
      publicReproducibleSql: false,
      methodologyDisclosed: true,
      largeSample: spec.analyzed >= 100_000,
      recentData: false,
      independentSecondSource: false,
    },
    periodStart: "2025-01-01",
    periodEnd: "2025-08-15",
    lastUpdated: "2025-08-15T00:00:00.000Z",
  };
}

