export function demoPlatforms(): Platform[] {
  const generated: Platform[] = DEMO_SPECS.map((spec) => ({
    slug: spec.slug,
    name: spec.name,
    category: spec.category,
    description: spec.description,
    chains: spec.chains,
    website: spec.website,
    stat: buildStat(spec),
    unknownReason: null,
    dataAvailabilityNote: null,
    isDemo: true,
  }));
  return [...generated, ...UNKNOWN_PLATFORMS];
}
